// Generated from src/registry/sources/control-ui/recipes/breadcrumb.css by scripts/gen-knob-contracts.ts — run `bun run sync:knobs`.
export const breadcrumbKnobs = [
  "--cui-breadcrumb-list-foreground",
  "--cui-breadcrumb-page-foreground",
  "--cui-breadcrumb-link-hover-foreground",
] as const;
export type BreadcrumbKnobStyle = Partial<Record<(typeof breadcrumbKnobs)[number], string>>;

@layer components {
  :where([data-control-family="breadcrumb"][data-slot="root"]) {
    --cui-breadcrumb-list-foreground: var(--muted-foreground);
    --cui-breadcrumb-page-foreground: var(--foreground);
    --cui-breadcrumb-link-hover-foreground: var(--foreground);
  }

  :where([data-control-family="breadcrumb"][data-slot="page"]) {
    font-weight: var(--font-weight-normal);
    color: var(--cui-breadcrumb-page-foreground);
  }

  :where([data-control-family="breadcrumb"][data-slot="list"]) {
    gap: calc(var(--spacing) * 1.5);
    font-size: var(--text-body);
    line-height: var(--text-body--line-height);
    color: var(--cui-breadcrumb-list-foreground);
  }

  @media (width >= 40rem) {
    :where([data-control-family="breadcrumb"][data-slot="list"]) {
      gap: calc(var(--spacing) * 2.5);
    }
  }

  :where([data-control-family="breadcrumb"][data-slot="item"]) {
    gap: calc(var(--spacing) * 1.5);
  }

  :where([data-control-family="breadcrumb"][data-slot="link"]) {
    transition: color var(--duration-fast) var(--ease-standard);
  }

  @media (hover: hover) {
    :where([data-control-family="breadcrumb"][data-slot="link"]:hover:not(:disabled, [data-disabled], [aria-disabled="true"])) {
      color: var(--cui-breadcrumb-link-hover-foreground);
    }
  }

  :where([data-control-family="breadcrumb"][data-slot="link"]:is(:disabled, [aria-disabled="true"])) {
    opacity: var(--disabled-opacity);
    cursor: not-allowed;
  }

  :where([data-control-family="breadcrumb"][data-slot="separator"] > svg) {
    inline-size: calc(var(--spacing) * 3.5);
    block-size: calc(var(--spacing) * 3.5);
  }

  :where([data-control-family="breadcrumb"][data-slot="ellipsis"]) {
    inline-size: var(--control-h-md);
    block-size: var(--control-h-md);
  }

  :where([data-control-family="breadcrumb"][data-slot="ellipsis"] > svg) {
    inline-size: calc(var(--spacing) * 4);
    block-size: calc(var(--spacing) * 4);
  }

  @media (pointer: coarse) {
    :where([data-control-family="breadcrumb"][data-slot="link"]) {
      position: relative;
    }

    :where([data-control-family="breadcrumb"][data-slot="link"])::after {
      content: "";
      position: absolute;
      inset-inline: 0;
      inset-block-start: 50%;
      translate: 0 -50%;
      block-size: max(100%, var(--touch-target));
    }
  }
}

@property --cui-breadcrumb-list-foreground {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-breadcrumb-page-foreground {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-breadcrumb-link-hover-foreground {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

"use client";

import { useRender } from "@base-ui/react/use-render";
import { ChevronRight, MoreHorizontal } from "lucide-react";
import type { ComponentProps, CSSProperties } from "react";
import type { RenderProp } from "@/components/control-ui/control-props";
import type { BreadcrumbKnobStyle } from "@/components/control-ui/knob-contracts/breadcrumb-knobs";
import { cn } from "@/components/control-ui/lib/cn";

export type BreadcrumbProps = ComponentProps<"nav"> & { style?: CSSProperties & BreadcrumbKnobStyle };
export type BreadcrumbListProps = Omit<ComponentProps<"ol">, "style"> & { style?: CSSProperties & BreadcrumbKnobStyle };
export type BreadcrumbItemProps = ComponentProps<"li"> & { style?: CSSProperties & BreadcrumbKnobStyle };
export type BreadcrumbLinkProps = Omit<ComponentProps<"a">, "style"> & {
  render?: RenderProp<ComponentProps<"a">>;
  style?: CSSProperties & BreadcrumbKnobStyle;
};
export type BreadcrumbPageProps = Omit<ComponentProps<"span">, "style"> & { style?: CSSProperties & BreadcrumbKnobStyle };
export type BreadcrumbSeparatorProps = ComponentProps<"li"> & { style?: CSSProperties & BreadcrumbKnobStyle };
export type BreadcrumbEllipsisProps = Omit<ComponentProps<"span">, "children"> & {
  label?: string;
  style?: CSSProperties & BreadcrumbKnobStyle;
};

export function Breadcrumb({ className, ...props }: BreadcrumbProps) {
  return (
    <nav
      aria-label="Breadcrumb"
      data-control-ui="breadcrumb"
      data-control-family="breadcrumb"
      data-slot="root"
      className={className}
      {...props}
    />
  );
}

export function BreadcrumbList({ className, ...props }: BreadcrumbListProps) {
  return (
    <ol
      data-control-ui="breadcrumb"
      data-control-family="breadcrumb"
      data-slot="list"
      className={cn("flex flex-wrap items-center break-words", className)}
      {...props}
    />
  );
}

export function BreadcrumbItem({ className, ...props }: BreadcrumbItemProps) {
  return (
    <li
      data-control-ui="breadcrumb"
      data-control-family="breadcrumb"
      data-slot="item"
      className={cn("inline-flex items-center", className)}
      {...props}
    />
  );
}

export function BreadcrumbLink({ render, className, children, ...props }: BreadcrumbLinkProps) {
  return useRender({
    defaultTagName: "a",
    render,
    props: {
      ...props,
      "data-control-ui": "breadcrumb",
      "data-control-family": "breadcrumb",
      "data-slot": "link",
      className: className,
      children,
    },
  });
}

export function BreadcrumbPage({ className, ...props }: BreadcrumbPageProps) {
  return (
    <span
      data-control-ui="breadcrumb"
      data-control-family="breadcrumb"
      data-slot="page"
      aria-current="page"
      className={className}
      {...props}
    />
  );
}

export function BreadcrumbSeparator({ children, className, ...props }: BreadcrumbSeparatorProps) {
  return (
    <li
      data-control-ui="breadcrumb"
      data-control-family="breadcrumb"
      data-slot="separator"
      role="presentation"
      aria-hidden="true"
      className={className}
      {...props}
    >
      {children ?? <ChevronRight data-icon-dir="inline" />}
    </li>
  );
}

export function BreadcrumbEllipsis({ label = "Show hidden breadcrumbs", className, ...props }: BreadcrumbEllipsisProps) {
  return (
    <span
      data-control-ui="breadcrumb"
      data-control-family="breadcrumb"
      data-slot="ellipsis"
      className={cn("flex items-center justify-center", className)}
      {...props}
    >
      <MoreHorizontal aria-hidden="true" />
      <span className="sr-only">{label}</span>
    </span>
  );
}
